<script setup lang="ts">
import ModalShell from '../../shared/ModalShell.vue';
import { inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { api, displayTime, errorMessage, today, type Me, type WorkItem } from '@worktime/api-client';
import { reporting, type Capabilities, type Period, type ScopeInput } from '../../shared/reporting';
const me=inject<Ref<Me|undefined>>('me'),sharedBusy=inject<Ref<boolean>>('operationBusy'),busy=ref(false),error=ref(''),notice=ref(''),month=ref(today().slice(0,7)),period=ref<Period>(),caps=ref<Capabilities>();
const objects=ref<WorkItem[]>([]);
const closingLabels:Record<string,string>={TIME:'工时记录',ONSITE:'现场记录',BASE:'每日应填工时',DAY:'每日填报情况',ADD:'新增记录',SAVE:'保存修改',SUBMIT:'提交审批',APPROVE:'审批通过',REJECT:'驳回',CORRECT:'更正记录',DISPUTE:'处理争议',TRANSFER:'转交审批',REQUESTED:'待受理',GRANTED:'已受理',CANCEL:'取消',CHANGE:'修改'};
function closingLabel(value:unknown){return closingLabels[String(value)]??String(value);}
const modal=ref(''),reason=ref(''),requestId=ref(''),diff=ref<{fromVersionId:string;toVersionId:string|null;rows:Record<string,unknown>[]} >(),scope=ref<ScopeInput>(freshScope());
function freshScope():ScopeInput{return {userId:me?.value?.id??'',date:month.value+'-01',workItemId:null,objectType:'TIME',recordId:null,actions:['SAVE','SUBMIT','APPROVE'],reason:''};}
watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
async function load(){busy.value=true;error.value='';diff.value=undefined;try{period.value=await reporting.period(month.value);}catch(e){period.value=undefined;error.value=errorMessage(e);}finally{busy.value=false;}}
function open(action:string,id=''){modal.value=action;reason.value='';requestId.value=id;scope.value=freshScope();error.value='';}
async function inspect(id:string){busy.value=true;error.value='';try{diff.value=id==='current'?await reporting.amendmentDiff(month.value,period.value!.activeAmendment!.id):await reporting.diff(month.value,id);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function commit(){busy.value=true;error.value='';try{if(modal.value==='close')await reporting.close(month.value);else if(modal.value==='request')await reporting.request(month.value,reason.value,[{...scope.value,recordId:scope.value.recordId||null,reason:reason.value}]);else if(modal.value==='amend')await reporting.amend(month.value,reason.value,requestId.value||undefined);else if(modal.value==='scope')await reporting.scope(month.value,period.value!.activeAmendment!.id,{...scope.value,recordId:scope.value.recordId||null,reason:reason.value});else if(modal.value==='publish')await reporting.publish(month.value,period.value!.activeAmendment!.id,reason.value);modal.value='';notice.value='操作已完成，月份状态已更新。';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
function objectChanged(){if(scope.value.objectType==='BASE'){scope.value.workItemId=null;scope.value.recordId=null;scope.value.actions=['BASE'];}else scope.value.actions=['SAVE','SUBMIT','APPROVE'];}
onMounted(async()=>{try{caps.value=await reporting.capabilities();objects.value=(await api.catalog()).workItems;await load();}catch(e){error.value=errorMessage(e);}});onBeforeRouteLeave(()=>!busy.value&&(!modal.value||!reason.value||window.confirm('已填写的说明尚未提交，确定离开？')));onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>月度结算</h1><p>封账后生成正式月报。补录、补审或更正需先获准处理指定记录，再发布新版月报；历史版本始终保留。</p></div><form class="workflow-filters" @submit.prevent="load"><label>结算月份<input v-model="month" type="month" required :disabled="busy" /></label><button :disabled="busy">查询</button></form></div><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><template v-if="period"><section class="workflow-panel"><div class="workflow-between"><h2>{{ period.month }} 月</h2><span class="workflow-tag" :data-state="period.status === 'AMENDING' ? 'AMENDING' : undefined">{{ ({OPEN:'可填报',CLOSING:'待封账',CLOSED:'已封账',AMENDING:'修订中'} as Record<string,string>)[period.status]??period.status }}</span></div><p>计划封账 {{ displayTime(period.scheduledCloseAt) }} · 实际封账 {{ displayTime(period.actualClosedAt) }}</p><div class="workflow-actions"><button v-if="period.canClose&&!period.latestVersionId" class="primary" :disabled="busy" @click="open('close')">封账并生成月报</button><button v-if="period.latestVersionId" :disabled="busy" @click="open('request')">申请月报修订</button><button v-if="period.canUnlock&&period.latestVersionId&&!period.activeAmendment" :disabled="busy" @click="open('amend')">发起月报修订</button></div><p class="workflow-note">封账会保留已确认记录，并列出缺填和未确认记录。未确认记录继续保留原审批状态，不计入已确认成本。</p></section><section v-if="period.activeAmendment" class="workflow-panel"><div class="workflow-between"><h2>本次月报修订 {{ period.activeAmendment.id }}</h2><span>{{ period.activeAmendment.reason }}</span></div><p class="workflow-note">请先授权需要处理的记录。授权不代表审批通过；新版发布前，正式报表仍使用上一版。</p><div class="workflow-actions"><button v-if="period.canUnlock" :disabled="busy" @click="open('scope')">授权处理范围</button><button :disabled="busy" @click="inspect('current')">查看本次修改</button><button v-if="period.canPublish" class="primary" :disabled="busy||!diff||diff.toVersionId!==null" @click="open('publish')">发布新版月报</button></div><p v-if="!period.scopes.length">尚未授权处理任何记录。请先指定人员、日期和可执行的操作。</p><article v-for="item in period.scopes" :key="item.id" class="workflow-readonly"><p>{{ item.date }} · 人员 {{ caps?.users.find(u=>u.id===item.userId)?.name??item.userId }} · {{ item.objectType==='BASE'?'每日应填工时':caps?.projects.find(w=>w.id===item.workItemId)?.name??item.workItemId }} · {{ item.objectType==='BASE'?'当日应填工时调整':item.recordId?`记录 ${item.recordId}`:'仅限授权后新增的记录' }}</p><p>允许操作 {{ item.actions.map(closingLabel).join('、') }} · {{ item.active?'授权有效':'已关闭' }} · {{ item.reason }}</p></article></section><section v-if="diff" class="workflow-panel"><h2>版本对比 · {{ diff.fromVersionId }} → {{ diff.toVersionId??'本次修订' }}</h2><p v-if="!diff.rows.length">所选范围没有变化。</p><details v-for="(row,i) in diff.rows" :key="i"><summary>{{ closingLabel(row.kind) }} · 记录 {{ row.recordId }} · {{ closingLabel(row.change) }}</summary><p>变更前</p><pre>{{ JSON.stringify(row.before,null,2) }}</pre><p>变更后</p><pre>{{ JSON.stringify(row.after,null,2) }}</pre></details></section><section class="workflow-panel"><h2>正式版本</h2><p v-if="!period.versions.length">本月尚未发布正式月报。</p><article v-for="version in period.versions" :key="version.id" class="version-row"><div><strong>V{{ version.versionNo }} · {{ version.month }}</strong><p>数据截至 {{ displayTime(version.cutoffAt) }} · 发布 {{ displayTime(version.publishedAt) }}</p><small>{{ version.reason }}</small></div><div class="workflow-actions"><RouterLink :to="`/reports/workload?version=${version.id}&month=${month}`">查看正式报表</RouterLink><button v-if="version.previousVersionId" :disabled="busy" @click="inspect(version.id)">比较上一版本</button></div></article></section><section class="workflow-panel"><h2>修订申请</h2><p v-if="!period.requests.length">暂无修订申请。</p><article v-for="item in period.requests" :key="item.id" class="version-row"><div><strong>申请 {{ item.id }} · {{ closingLabel(item.state) }}</strong><p>{{ item.reason }}</p><p v-for="(s,i) in item.scopes" :key="i">{{ s.date }} · {{ closingLabel(s.objectType) }} · {{ s.objectType==='BASE'?'当日应填工时调整':s.recordId?`记录 ${s.recordId}`:'新增记录' }} · {{ s.actions.map(closingLabel).join('、') }}</p></div><button v-if="period.canUnlock" :disabled="busy" @click="open('amend',item.id)">受理并发起修订</button></article></section></template><ModalShell v-if="modal" :busy="busy" @close="modal=''"><div class="workflow-overlay"><section class="workflow-dialog" role="dialog" aria-modal="true" aria-label="月度结算操作"><h2>{{ ({close:'封账并生成月报',request:'申请月报修订',amend:'发起月报修订',scope:'授权处理范围',publish:'发布新版月报'} as Record<string,string>)[modal] }}</h2><p v-if="modal==='publish'">发布后，生成截至发布时的整月新版本，本次处理授权随之关闭。尚未确认的记录仍单独列示，原月报版本保留。</p><form @submit.prevent="commit"><template v-if="['request','scope'].includes(modal)"><label>人员<select aria-label="人员" v-model="scope.userId" required :disabled="busy"><option v-for="u in caps?.users" :value="u.id" :key="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><label>日期<input v-model="scope.date" type="date" required :min="month+'-01'" :disabled="busy" /></label><label>记录类型<select aria-label="记录类型" v-model="scope.objectType" :disabled="busy" @change="objectChanged"><option value="TIME">工时</option><option value="ONSITE">现场日</option><option v-if="me?.canManage" value="BASE">每日应填工时</option></select></label><label v-if="scope.objectType!=='BASE'">项目或事项<select aria-label="项目或事项" v-model="scope.workItemId" required :disabled="busy"><option :value="null">选择项目或事项</option><option v-for="w in objects" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label v-if="scope.objectType!=='BASE'">原记录 ID<input v-model="scope.recordId" placeholder="仅新增记录时留空；处理已有记录时填写 ID" :disabled="busy" /></label><div v-if="scope.objectType!=='BASE'" class="workflow-actions"><label v-for="a in [{id:'ADD',name:'新增'},{id:'SAVE',name:'保存'},{id:'SUBMIT',name:'提交审批'},{id:'APPROVE',name:'审批通过'},{id:'REJECT',name:'驳回'},{id:'CORRECT',name:'更正'},{id:'DISPUTE',name:'处理争议'},{id:'TRANSFER',name:'转交审批'}]" :key="a.id"><input v-model="scope.actions" type="checkbox" :value="a.id" :disabled="busy" />{{ a.name }}</label></div></template><label>原因说明<textarea v-model="reason" rows="3" :required="modal!=='close'" maxlength="1000" :disabled="busy" /></label><p v-if="error" class="workflow-error">{{ error }}</p><div class="workflow-actions"><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" type="submit" :disabled="busy||(['request','scope'].includes(modal)&&!scope.actions.length)">{{ busy?'正在处理…':({close:'确认封账',request:'提交申请',amend:'发起修订',scope:'确认授权',publish:'确认发布'} as Record<string,string>)[modal] }}</button></div></form></section></div></ModalShell></div></template>
<style scoped>
.version-row { display: flex; align-items: center; justify-content: space-between; gap: var(--ts-space-16); padding: var(--ts-space-20) 0; border-bottom: 1px solid var(--ts-color-divider); }
.version-row > * { min-width: 0; overflow-wrap: anywhere; }
.workflow-readonly { margin-top: var(--ts-space-16); }
@media (max-width: 700px) { .version-row { display: block; } }
</style>
